const raw = $input.item.json.body ?? $input.item.json;

const origemMap = {
  whatsapp: 'whatsapp',
  lovable: 'lovable',
  instagram: 'instagram_futuro',
  loja: 'atendimento_loja'
};
const origem_lead = origemMap[raw.canal] ?? 'whatsapp';

const history = (raw.contexto ?? [])
  .filter(m => m.tipo !== 'interno')
  .slice(-10)
  .map(m => ({
    role: m.tipo === 'cliente' ? 'cliente' : m.tipo === 'bia' ? 'bia' : 'atendente',
    text: m.texto,
    at: m.criadoEm
  }));

const is_first_contact = history.filter(m => m.role === 'cliente').length <= 1;

let pre_qualified = { uso_principal: null, orcamento: null, estado: null, prioridade: null };
if (origem_lead === 'lovable') {
  try {
    const pq = JSON.parse(raw.mensagemCliente);
    pre_qualified = {
      uso_principal: pq.uso_principal ?? null,
      orcamento: pq.orcamento ?? null,
      estado: pq.estado ?? null,
      prioridade: pq.prioridade ?? null
    };
  } catch (_) {}
}

return {
  json: {
    lead_id: raw.leadId,
    lead_nome: raw.leadNome ?? null,
    origem_lead,
    current_message: raw.mensagemCliente,
    resumo: raw.resumo ?? null,
    is_first_contact,
    history,
    pre_qualified
  }
};

const j = $input.item.json;

const SYSTEM = `Você é BIA, assistente de pré-vendas da TeknosCel — concessionária especializada em iPhones.

MISSÃO:
Responder rápido, gerar valor, qualificar o lead e encaminhar ao vendedor humano no momento certo. Você não fecha vendas. Você aquece e prepara o terreno.

TOM: profissional, direto, acolhedor. Português brasileiro natural. Nunca robótico.

SOBRE SEMINOVOS TEKNOSCEL:
- Aparelhos revisados, garantia de 6 meses da loja, acompanham kit de proteção
- NÃO informe: saúde da bateria, quantidade em estoque, disponibilidade específica

SOBRE LACRADOS TEKNOSCEL:
- Nota fiscal, 1 ano de garantia Apple, +6 meses adicional da loja

REGRAS IMUTÁVEIS — NUNCA VIOLE:
1. Nunca afirme disponibilidade ou estoque
2. Nunca invente desconto, promoção ou condição especial
3. Nunca confirme reserva
4. Nunca informe saúde de bateria
5. Nunca informe quantidade exata
6. Nunca discuta com o cliente
7. Assistência técnica: máx 2 perguntas + 1 orientação + encaminhar humano

Se perguntarem sobre estoque/bateria/disponibilidade: diga que o time de vendas tem essa informação em tempo real e ofereça conexão imediata.

LEADS PRÉ-QUALIFICADOS (origem = lovable):
O cliente já informou uso, orçamento, estado e prioridade. NÃO repita essas perguntas. Vá direto ao valor: "Com base no que você nos informou, [insight personalizado]."

FORMATO DE SAÍDA OBRIGATÓRIO — responda APENAS com JSON válido, sem texto fora do JSON:
{
  "intencao": "produto | preco | seminovo | assistencia | troca | outro",
  "complexidade": "simples | media | complexa",
  "lead_score": 0,
  "urgencia": "baixa | media | alta",
  "humano": false,
  "estado_atendimento": "novo | qualificando | interessado | negociando | aguardando | handoff_humano | fechado | perdido",
  "resumo": "1 linha com o que o cliente quer e onde está na jornada",
  "response_text": "mensagem da BIA para o cliente — texto puro, sem markdown"
}

lead_score: 8-10 = intenção clara de compra | 5-7 = interesse real | 0-4 = curiosidade.
humano=true quando: lead_score >= 8 OU cliente pediu humano OU situação fora do escopo da BIA.`;

const hist = (j.history ?? [])
  .map(m => `[${m.role}]: ${m.text}`)
  .join('\n') || '(sem histórico)';

const pqLines = j.origem_lead === 'lovable'
  ? `Uso principal: ${j.pre_qualified.uso_principal ?? '-'}\nOrçamento: ${j.pre_qualified.orcamento ?? '-'}\nEstado: ${j.pre_qualified.estado ?? '-'}\nPrioridade: ${j.pre_qualified.prioridade ?? '-'}`
  : 'N/A (lead whatsapp — coletar durante conversa)';

const mem = j.memoria ?? {};
const memLinhas = [];
if (mem.resumo) memLinhas.push('Resumo do atendimento: ' + mem.resumo);
if (mem.estado_atendimento) memLinhas.push('Estado: ' + mem.estado_atendimento);
if (mem.intencao) memLinhas.push('Intenção: ' + mem.intencao);
if (mem.lead_score != null) memLinhas.push('Score: ' + mem.lead_score);
if (mem.ultima_mensagem) memLinhas.push('Última resposta da BIA: ' + mem.ultima_mensagem);
const atendAnterior = (mem.atendimentos ?? [])
  .filter(m => m.papel === 'cliente' || m.papel === 'bia')
  .slice(-10)
  .map(m => '[' + m.papel + ']: ' + m.texto)
  .join('\n');
if (atendAnterior) { memLinhas.push('Atendimentos anteriores:'); memLinhas.push(atendAnterior); }
const memoriaBlock = memLinhas.length ? memLinhas.join('\n') : '(sem memória registrada)';

const prompt = [
  SYSTEM,
  '----------------------------------------',
  `ORIGEM: ${j.origem_lead}`,
  `LEAD: ${j.lead_nome ?? 'não identificado'}`,
  `PRIMEIRO CONTATO: ${j.is_first_contact ? 'sim' : 'não'}`,
  `RESUMO ANTERIOR: ${j.resumo ?? 'nenhum'}`,
  '',
  'HISTÓRICO (últimas 10 msgs):',
  hist,
  '',
  'CONTEXTO REGISTRADO (memória):',
  memoriaBlock,
  '',
  'PRÉ-QUALIFICAÇÃO:',
  pqLines,
  '',
  'MENSAGEM ATUAL DO CLIENTE:',
  j.current_message
].join('\n');

return {
  json: {
    ...j,
    prompt
  }
};

const raw = $input.item.json;
const classificacao = raw.output ?? raw;
const normalizado = $('normalizar_entrada').item.json;

const blacklist = [
  'em estoque', 'disponível', 'temos disponível', 'tenho aqui',
  'saúde da bateria', 'bateria está', 'capacidade da bateria',
  'desconto', 'promoção especial', 'condição especial',
  'reservado', 'posso reservar', 'vou reservar',
  'garanto', 'confirmo disponibilidade'
];

let response_text = classificacao.response_text ?? 'Nosso time de vendas pode te ajudar! Posso conectar você agora?';
let humano = classificacao.humano ?? false;
let handoff_reason = null;

const lower = response_text.toLowerCase();
if (blacklist.some(kw => lower.includes(kw))) {
  response_text = 'Nosso time de vendas tem todas as informações atualizadas. Posso te conectar com eles agora?';
  humano = true;
  handoff_reason = 'violation_blacklist';
}

return {
  json: {
    crm_payload: {
      lead_id: normalizado.lead_id,
      respostas: [{ texto: response_text, mediaUrl: null }],
      metadata: {
        intencao: classificacao.intencao ?? 'outro',
        complexidade: classificacao.complexidade ?? 'simples',
        lead_score: classificacao.lead_score ?? 0,
        urgencia: classificacao.urgencia ?? 'baixa',
        estado_atendimento: classificacao.estado_atendimento ?? 'qualificando',
        origem_lead: normalizado.origem_lead,
        resumo: classificacao.resumo ?? null,
        humano,
        handoff_reason
      }
    }
  }
};

const { DatabaseSync } = require('node:sqlite');
const payload = $input.item.json.crm_payload;
const normal = $('buscar_memoria').item.json;

const DB_PATH = '/home/node/workflows/bia_memoria.db';

function init(db) {
  db.exec("CREATE TABLE IF NOT EXISTS atendimentos (id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id TEXT NOT NULL, papel TEXT NOT NULL, texto TEXT, media_url TEXT, criado_em TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')))");
  db.exec("CREATE TABLE IF NOT EXISTS memorias (lead_id TEXT PRIMARY KEY, resumo TEXT, intencao TEXT, lead_score INTEGER, estado_atendimento TEXT, ultima_mensagem TEXT, atualizado_em TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')))");
  db.exec('CREATE INDEX IF NOT EXISTS idx_atendimentos_lead ON atendimentos(lead_id)');
}

const db = new DatabaseSync(DB_PATH);
init(db);

const leadId = payload.lead_id;
const respText = (payload.respostas && payload.respostas[0] && payload.respostas[0].texto) || null;

const ins = db.prepare('INSERT INTO atendimentos (lead_id, papel, texto) VALUES (?, ?, ?)');
if (normal.current_message) ins.run(leadId, 'cliente', normal.current_message);
if (respText) ins.run(leadId, 'bia', respText);

const m = payload.metadata || {};
const ups = db.prepare("INSERT INTO memorias (lead_id, resumo, intencao, lead_score, estado_atendimento, ultima_mensagem) VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT(lead_id) DO UPDATE SET resumo=excluded.resumo, intencao=excluded.intencao, lead_score=excluded.lead_score, estado_atendimento=excluded.estado_atendimento, ultima_mensagem=excluded.ultima_mensagem, atualizado_em=strftime('%Y-%m-%dT%H:%M:%fZ','now')");
ups.run(leadId, m.resumo || null, m.intencao || null, m.lead_score || 0, m.estado_atendimento || null, respText);

const total = db.prepare('SELECT COUNT(*) AS c FROM atendimentos WHERE lead_id = ?').get(leadId).c;
db.close();

return { json: { crm_payload: payload, _memoria: { ok: true, lead_id: leadId, atendimentos_gravados: total, resposta_gravada: !!respText } } };

const { DatabaseSync } = require('node:sqlite');
const j = $input.item.json;

const DB_PATH = '/home/node/workflows/bia_memoria.db';

function init(db) {
  db.exec("CREATE TABLE IF NOT EXISTS atendimentos (id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id TEXT NOT NULL, papel TEXT NOT NULL, texto TEXT, media_url TEXT, criado_em TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')))");
  db.exec("CREATE TABLE IF NOT EXISTS memorias (lead_id TEXT PRIMARY KEY, resumo TEXT, intencao TEXT, lead_score INTEGER, estado_atendimento TEXT, ultima_mensagem TEXT, atualizado_em TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')))");
  db.exec('CREATE INDEX IF NOT EXISTS idx_atendimentos_lead ON atendimentos(lead_id)');
}

const db = new DatabaseSync(DB_PATH);
init(db);
const atendimentos = db.prepare('SELECT papel, texto, criado_em FROM atendimentos WHERE lead_id = ? ORDER BY id ASC').all(j.lead_id);
const memo = db.prepare('SELECT resumo, intencao, lead_score, estado_atendimento, ultima_mensagem, atualizado_em FROM memorias WHERE lead_id = ?').get(j.lead_id);
db.close();

return {
  json: {
    ...j,
    memoria: {
      resumo: memo ? memo.resumo : null,
      intencao: memo ? memo.intencao : null,
      lead_score: memo ? memo.lead_score : null,
      estado_atendimento: memo ? memo.estado_atendimento : null,
      ultima_mensagem: memo ? memo.ultima_mensagem : null,
      atualizado_em: memo ? memo.atualizado_em : null,
      atendimentos
    }
  }
};
